int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *m,
                 size_t buf_len, int flags)
{
    int ret = 0;
    struct sk_buff *skb;

    if (!sock || !m || !buf_len)
        return -EINVAL;

    lock_sock(sock);

    while (ret < (int)buf_len) {
        skb = skb_dequeue(&sock->sk->sk_receive_queue);
        if (!skb) {
            if (signal_pending(current)) {
                ret = -ERESTARTSYS;
                break;
            }

            if (sock->sk->sk_shutdown & RCV_SHUTDOWN) {
                if (ret == 0)
                    ret = -ENODATA;
                break;
            }

            skb = skb_peek(&sock->sk->sk_receive_queue);
            if (!skb)
                break;
        }

        int copy_len = min(skb->len, buf_len - ret);
        ret += memcpy_toiovec(m->msg_iov, skb->data, copy_len);

        if (copy_len < skb->len)
            skb_pull(skb, copy_len);
        else
            skb_dequeue(&sock->sk->sk_receive_queue);

        if (flags & MSG_WAITALL && (size_t)ret < buf_len)
            continue;
        else
            break;
    }

    release_sock(sock);

    return (ret < 0) ? ret : (ret > 0 ? ret : -ENODATA);
}

int recv_socket_message(struct kiocb *iocb, struct socket *sock, struct msghdr *m,
                        size_t buf_len, int flags) {
    int copied = 0;
    struct sock *sk = sock->sk;
    int err = 0;

    if (unlikely(!(iocb->ki_flags & IOCB_DIRECT))) {
        return -EINVAL;
    }

    lock_sock(sk);

    while (copied < (int)buf_len) {
        struct sk_buff *skb;
        int skb_len;

        skb = skb_peek(&sk->sk_receive_queue);
        if (!skb) {
            if (flags & MSG_DONTWAIT) {
                err = -EAGAIN;
                break;
            }

            if (skb_queue_empty(&sk->sk_error_queue)) {
                if (sk->sk_shutdown & RCV_SHUTDOWN) {
                    err = -ENODATA;
                    break;
                }
            }

            release_sock(sk);
            schedule();
            lock_sock(sk);
            continue;
        }

        skb_len = skb->len;
        if (skb_len <= 0) {
            skb = skb_dequeue(&sk->sk_receive_queue);
            skb_queue_purge(&sk->sk_receive_queue);
            kfree_skb(skb);
            continue;
        }

        int copy_len = min(skb_len, (int)buf_len - copied);
        err = skb_copy_datagram_iovec(skb, 0, m, copy_len);
        if (err) {
            break;
        }

        copied += copy_len;

        if (skb->len <= copy_len) {
            skb = skb_dequeue(&sk->sk_receive_queue);
        } else {
            skb_pull(skb, copy_len);
        }

        kfree_skb(skb);
    }

    release_sock(sk);
    if (err) {
        return err;
    }
    return copied;
}

int sock_recv_data(struct kiocb *iocb, struct socket *sock, struct msghdr *m,
                   size_t buf_len, int flags) {
    int ret;
    size_t copied = 0;
    struct sk_buff *skb;
    struct iovec *iov = m->msg_iov;
    size_t iov_len = m->msg_iovlen;
    size_t total_len = 0;

    if (!sock || !m || !iov_len || !buf_len) {
        return -EINVAL;
    }

    lock_sock(sock->sk);

    while (copied < buf_len) {
        skb = skb_peek(&sock->sk->sk_receive_queue);
        if (!skb) {
            ret = sock_wait_for_data(sock, flags);
            if (ret < 0) {
                unlock_sock(sock->sk);
                return ret;
            }
            continue;
        }

        total_len = skb->len;

        if (total_len <= 0) {
            skb = skb_dequeue(&sock->sk->sk_receive_queue);
            sock_skb_free(skb);
            continue;
        }

        if (copied + total_len > buf_len) {
            total_len = buf_len - copied;
        }

        ret = skb_copy_datagram_iovec(skb, 0, iov, total_len);
        if (ret < 0) {
            unlock_sock(sock->sk);
            return ret;
        }

        copied += total_len;
        skb = skb_dequeue(&sock->sk->sk_receive_queue);
        sock_skb_free(skb);

        if (copied >= buf_len)
            break;
    }

    unlock_sock(sock->sk);
    return copied ? (int)copied : -ENODATA;
}

int recv_socket_data(struct kiocb *iocb, struct socket *sock, struct msghdr *m, size_t buf_len, int flags) {
    int bytes_copied = 0;
    int result = 0;

    if (!sock || !m) {
        return -EINVAL;
    }

    lock_sock(sock);

    while (bytes_copied < buf_len) {
        result = sock->ops->recvmsg(iocb, sock, m, buf_len - bytes_copied, flags);

        if (result <= 0) {
            if (result == 0 || result == -EAGAIN) {
                unlock_sock(sock);
                return bytes_copied ? bytes_copied : result;
            }

            unlock_sock(sock);
            return result;
        }

        bytes_copied += result;
        m->msg_flags = 0;
    }

    unlock_sock(sock);
    return bytes_copied;
}

int recv_socket_data(struct kiocb *iocb, struct socket *sock, struct msghdr *m, size_t buf_len, int flags) {
    int ret = 0;
    size_t copied = 0;

    if (!sock || !m || !buf_len) {
        return -EINVAL;
    }

    lock_sock(sock);

    while (copied < buf_len) {
        struct sk_buff *skb = skb_peek(&sock->sk->sk_receive_queue);
        if (!skb) {
            if (signal_pending(current) || sock->sk->sk_shutdown & RCV_SHUTDOWN) {
                if (copied == 0) {
                    ret = -EAGAIN;
                }
                break;
            }
            wait_for_rx(sock);
            continue;
        }

        int len = skb->len;
        int copy_len = min(buf_len - copied, (size_t)len);
        ret = skb_copy_datagram_iovec(skb, 0, m->msg_iov, copy_len);
        if (ret < 0) {
            break;
        }

        copied += copy_len;
        skb_pull(skb, copy_len);
        if (skb->len == 0) {
            skb_unlink(skb, &sock->sk->sk_receive_queue);
            kfree_skb(skb);
        }
    }

    release_sock(sock);
    return copied ? copied : ret;
}
